/// <summary>
/// This class handles the main processing to perform the Update stock availlability details on Item default order settings.
/// </summary>
internal final class METUpdateStockAvailabilityService extends SysOperationServiceBase
{
    #define.EmptyString('')
    InventSiteId inventSiteId;
    ItemId itemId;
    METStockAvailDate stockAvailabilityDate;
    EcoResProductLifecycleStateId productLifeCycleStateId;

    Set processedItemSitePairs = new Set(Types::Container);
    Set porcessedItemSitePairsUnderIntercompany = new Set(Types::Container);

    boolean haveIdentifiedClassifiedInitialWarehouses;
    Set identifiedClassifiedIntialWarehouseSet = new Set(Types::Container);



}

